#include "mc_trajectory.h"
void MC_Trajectory_Init(MC_TrajectoryPlanner_t *p) { if (p) *p = (MC_TrajectoryPlanner_t){0}; }
MC_TrajStatus_t MC_Trajectory_Start(MC_TrajectoryPlanner_t *p, const MC_TrajRequest_t *req) { if (!p || !req) return MC_TRAJ_ERR_INVALID_REQUEST; if (req->limits.max_jerk_rad_per_s3 <= 0.0f || req->limits.max_acceleration_rad_per_s2 <= 0.0f || req->limits.max_velocity_rad_per_s <= 0.0f) return MC_TRAJ_ERR_INVALID_LIMITS; if (req->target_velocity_rad_per_s != 0.0f || req->target_acceleration_rad_per_s2 != 0.0f) return MC_TRAJ_ERR_UNSUPPORTED_BOUNDARY; /* TODO: generate robust jerk-limited S-curve; placeholder returns stretched single segment. */ p->start = req->start; p->elapsed_time_s = 0.0f; p->segment_count = 0; p->info.requested_time_s = req->requested_time_s; p->info.planned_time_s = req->requested_time_s; p->info.time_stretched = false; p->info.status = MC_TRAJ_OK; p->active = true; return MC_TRAJ_OK; }
MC_TrajStatus_t MC_Trajectory_Replan(MC_TrajectoryPlanner_t *p, const MC_TrajRequest_t *req) { return MC_Trajectory_Start(p, req); }
MC_MotionSetpoint_t MC_Trajectory_Update(MC_TrajectoryPlanner_t *p, float dt_s) { MC_MotionSetpoint_t out = {0}; if (!p || !p->active) return out; p->elapsed_time_s += dt_s; out.valid = true; if (p->elapsed_time_s >= p->info.planned_time_s) { out.complete = true; p->active = false; p->info.status = MC_TRAJ_DONE; } return out; }
MC_MotionSetpoint_t MC_Trajectory_Evaluate(const MC_TrajectoryPlanner_t *p, float elapsed_time_s) { (void)elapsed_time_s; MC_MotionSetpoint_t out = {0}; if (p) out.valid = p->active; return out; }
MC_TrajPlanInfo_t MC_Trajectory_GetPlanInfo(const MC_TrajectoryPlanner_t *p) { return p ? p->info : (MC_TrajPlanInfo_t){0}; }
